before:
Complete local C++ example; the app itself does not execute it:
```cpp
#include <iostream>
template<typename T>
class Box {
    T item;
public:
    explicit Box(T value) : item{value} {}
    T get() const { return item; }
};
int main() {
    Box<int> count{3};
    Box<double> ratio{1.5};
    std::cout << count.get() << ' ' << ratio.get() << '\n';
}

```

